<span class="line"><span style="color:#C678DD;">        int</span><span style="color:#E06C75;"> rootY</span><span style="color:#56B6C2;"> =</span><span style="color:#61AFEF;"> Find</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">y</span><span style="color:#ABB2BF;">);</span></span>
